-- 0001 — core schema.
--
-- This is the first migration for a project that has never had a schema in
-- production, so everything here is additive. Every future change must be a new
-- migration file; never edit this one after it has been applied anywhere.
--
-- Conventions:
--   * every table lives in `public` and names its owner column `user_id` or an
--     explicit `<role>_id` (`author_id`, `reporter_id`, `moderator_id`);
--   * ids are `uuid` generated by the database, never by the client;
--   * timestamps are `timestamptz` and default to `now()`;
--   * no privilege-bearing column (role, moderation state, score) is writable
--     through the Data API — see 0002 for the grants that enforce this;
--   * nothing enforces authorization here: RLS is enabled in 0002, and until it
--     is, these tables are unreachable from the Data API.

create schema if not exists extensions;
create extension if not exists citext with schema extensions;

-- ─────────────────────────────────────────────────────────────────────────────
-- Enumerations
-- ─────────────────────────────────────────────────────────────────────────────

do $$
begin
  create type public.app_role as enum ('user', 'moderator', 'admin');
exception when duplicate_object then null;
end $$;
do $$
begin
  create type public.game_status as enum ('draft', 'review', 'published', 'rejected', 'archived');
exception when duplicate_object then null;
end $$;
do $$
begin
  create type public.like_target as enum ('game', 'comment');
exception when duplicate_object then null;
end $$;
do $$
begin
  create type public.report_target as enum ('game', 'comment', 'profile');
exception when duplicate_object then null;
end $$;
do $$
begin
  create type public.report_status as enum ('open', 'reviewing', 'resolved', 'dismissed');
exception when duplicate_object then null;
end $$;
do $$
begin
  create type public.notification_kind as enum ('follow', 'comment', 'like', 'score', 'moderation', 'system');
exception when duplicate_object then null;
end $$;

-- ─────────────────────────────────────────────────────────────────────────────
-- Identity
-- ─────────────────────────────────────────────────────────────────────────────

-- Application profile for an `auth.users` row. Credentials, email and MFA live
-- in `auth` and are never duplicated here.
create table if not exists public.profiles (
  id            uuid primary key references auth.users (id) on delete cascade,
  username      extensions.citext not null,
  display_name  text not null,
  bio           text,
  avatar_path   text,
  is_suspended  boolean not null default false,
  onboarded_at  timestamptz,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  constraint profiles_username_format check (username ~ '^[a-z0-9_]{3,24}$'),
  constraint profiles_display_name_length check (char_length(display_name) between 1 and 60),
  constraint profiles_bio_length check (bio is null or char_length(bio) <= 300),
  constraint profiles_avatar_path_format check (avatar_path is null or avatar_path ~ '^[0-9a-f-]{36}/[a-z0-9._-]{1,120}$')
);

create unique index if not exists profiles_username_key on public.profiles (username);
create index if not exists profiles_created_at_idx on public.profiles (created_at desc);

-- Roles are deliberately a separate table so that no update to `profiles` — by
-- a user, a buggy handler or a future feature — can grant a role. Only the
-- `service_role` and admins may write here (see 0002).
create table if not exists public.user_roles (
  user_id    uuid primary key references auth.users (id) on delete cascade,
  role       public.app_role not null default 'user',
  granted_at timestamptz not null default now(),
  granted_by uuid references auth.users (id) on delete set null
);

-- ─────────────────────────────────────────────────────────────────────────────
-- Catalogue
-- ─────────────────────────────────────────────────────────────────────────────

create table if not exists public.categories (
  id          uuid primary key default gen_random_uuid(),
  slug        extensions.citext not null,
  name        text not null,
  description text,
  sort_order  integer not null default 0,
  created_at  timestamptz not null default now(),
  constraint categories_slug_format check (slug ~ '^[a-z0-9-]{2,32}$'),
  constraint categories_name_length check (char_length(name) between 1 and 40)
);

create unique index if not exists categories_slug_key on public.categories (slug);

create table if not exists public.games (
  id            uuid primary key default gen_random_uuid(),
  owner_id      uuid not null references auth.users (id) on delete cascade,
  category_id   uuid references public.categories (id) on delete set null,
  slug          extensions.citext not null,
  title         text not null,
  tagline       text,
  description   text,
  status        public.game_status not null default 'draft',
  min_players   smallint not null default 1,
  max_players   smallint not null default 1,
  published_at  timestamptz,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  constraint games_slug_format check (slug ~ '^[a-z0-9-]{2,48}$'),
  constraint games_title_length check (char_length(title) between 1 and 80),
  constraint games_player_range check (min_players >= 1 and max_players >= min_players)
);

create unique index if not exists games_slug_key on public.games (slug);
create index if not exists games_status_published_idx on public.games (status, published_at desc nulls last);
create index if not exists games_owner_idx on public.games (owner_id);
create index if not exists games_category_idx on public.games (category_id);

-- ─────────────────────────────────────────────────────────────────────────────
-- Play
-- ─────────────────────────────────────────────────────────────────────────────

-- One row per play attempt. The server owns the seed and the start time, which
-- is what makes a score attributable to a real run.
create table if not exists public.game_sessions (
  id            uuid primary key default gen_random_uuid(),
  game_id       uuid not null references public.games (id) on delete cascade,
  user_id       uuid references auth.users (id) on delete cascade,
  seed          bigint not null default (floor(random() * 9223372036854775807)::bigint),
  client        text,
  started_at    timestamptz not null default now(),
  completed_at  timestamptz,
  abandoned_at  timestamptz,
  constraint game_sessions_single_end check (completed_at is null or abandoned_at is null)
);

create index if not exists game_sessions_user_idx on public.game_sessions (user_id, started_at desc);
create index if not exists game_sessions_game_idx on public.game_sessions (game_id, started_at desc);

-- Scores are written by the game-sessions service when a session completes.
-- Players can read them (leaderboards) but never insert or update one.
create table if not exists public.scores (
  id          uuid primary key default gen_random_uuid(),
  session_id  uuid not null unique references public.game_sessions (id) on delete cascade,
  game_id     uuid not null references public.games (id) on delete cascade,
  user_id     uuid not null references auth.users (id) on delete cascade,
  score       bigint not null,
  duration_ms integer,
  created_at  timestamptz not null default now(),
  constraint scores_score_range check (score >= 0),
  constraint scores_duration_range check (duration_ms is null or (duration_ms > 0 and duration_ms <= 86400000))
);

create index if not exists scores_leaderboard_idx on public.scores (game_id, score desc, created_at asc);
create index if not exists scores_user_idx on public.scores (user_id, created_at desc);

-- ─────────────────────────────────────────────────────────────────────────────
-- Social
-- ─────────────────────────────────────────────────────────────────────────────

create table if not exists public.comments (
  id          uuid primary key default gen_random_uuid(),
  game_id     uuid not null references public.games (id) on delete cascade,
  author_id   uuid not null references auth.users (id) on delete cascade,
  parent_id   uuid references public.comments (id) on delete cascade,
  body        text not null,
  is_hidden   boolean not null default false,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  constraint comments_body_length check (char_length(body) between 1 and 2000),
  -- No self-parent, no deeper-than-one-level threads: keeps moderation and
  -- pagination predictable.
  constraint comments_no_self_parent check (parent_id is null or parent_id <> id)
);

create index if not exists comments_game_idx on public.comments (game_id, created_at desc) where not is_hidden;
create index if not exists comments_author_idx on public.comments (author_id, created_at desc);
create index if not exists comments_parent_idx on public.comments (parent_id);

create table if not exists public.likes (
  user_id     uuid not null references auth.users (id) on delete cascade,
  target_kind public.like_target not null,
  target_id   uuid not null,
  created_at  timestamptz not null default now(),
  primary key (user_id, target_kind, target_id)
);

create index if not exists likes_target_idx on public.likes (target_kind, target_id);

create table if not exists public.follows (
  follower_id uuid not null references auth.users (id) on delete cascade,
  followee_id uuid not null references auth.users (id) on delete cascade,
  created_at  timestamptz not null default now(),
  primary key (follower_id, followee_id),
  constraint follows_no_self check (follower_id <> followee_id)
);

create index if not exists follows_followee_idx on public.follows (followee_id, created_at desc);

-- ─────────────────────────────────────────────────────────────────────────────
-- Moderation
-- ─────────────────────────────────────────────────────────────────────────────

create table if not exists public.reports (
  id           uuid primary key default gen_random_uuid(),
  reporter_id  uuid not null references auth.users (id) on delete cascade,
  target_kind  public.report_target not null,
  target_id    uuid not null,
  reason       text not null,
  details      text,
  status       public.report_status not null default 'open',
  resolved_by  uuid references auth.users (id) on delete set null,
  resolved_at  timestamptz,
  created_at   timestamptz not null default now(),
  constraint reports_reason_length check (char_length(reason) between 3 and 80),
  constraint reports_details_length check (details is null or char_length(details) <= 1000),
  constraint reports_resolution_consistent check (
    (status in ('open', 'reviewing') and resolved_at is null and resolved_by is null)
    or (status in ('resolved', 'dismissed') and resolved_at is not null)
  )
);

create index if not exists reports_queue_idx on public.reports (status, created_at asc);

create table if not exists public.moderation_actions (
  id            uuid primary key default gen_random_uuid(),
  moderator_id  uuid not null references auth.users (id) on delete restrict,
  target_kind   public.report_target not null,
  target_id     uuid not null,
  action        text not null,
  reason        text,
  created_at    timestamptz not null default now(),
  constraint moderation_actions_action_length check (char_length(action) between 3 and 40),
  constraint moderation_actions_reason_length check (reason is null or char_length(reason) <= 500)
);

create index if not exists moderation_actions_target_idx on public.moderation_actions (target_kind, target_id, created_at desc);

-- ─────────────────────────────────────────────────────────────────────────────
-- Messaging and analytics
-- ─────────────────────────────────────────────────────────────────────────────

create table if not exists public.notifications (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references auth.users (id) on delete cascade,
  kind       public.notification_kind not null,
  payload    jsonb not null default '{}'::jsonb,
  read_at    timestamptz,
  created_at timestamptz not null default now(),
  constraint notifications_payload_size check (pg_column_size(payload) <= 4096)
);

create index if not exists notifications_inbox_idx on public.notifications (user_id, created_at desc);
create index if not exists notifications_unread_idx on public.notifications (user_id) where read_at is null;

-- Append-only product analytics. Event names are constrained so a client cannot
-- write arbitrary text into the warehouse, and properties are size limited.
create table if not exists public.analytics_events (
  id         bigint generated always as identity primary key,
  user_id    uuid references auth.users (id) on delete set null,
  name       text not null,
  properties jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  constraint analytics_events_name_format check (name ~ '^[a-z][a-z0-9_.]{2,63}$'),
  constraint analytics_events_properties_size check (pg_column_size(properties) <= 8192)
);

create index if not exists analytics_events_name_time_idx on public.analytics_events (name, created_at desc);
create index if not exists analytics_events_user_idx on public.analytics_events (user_id, created_at desc) where user_id is not null;

-- ─────────────────────────────────────────────────────────────────────────────
-- Triggers
-- ─────────────────────────────────────────────────────────────────────────────

-- Keep `updated_at` honest without trusting the client to send it.
create or replace function public.touch_updated_at()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists profiles_touch_updated_at on public.profiles;
create trigger profiles_touch_updated_at
  before update on public.profiles
  for each row execute function public.touch_updated_at();

drop trigger if exists games_touch_updated_at on public.games;
create trigger games_touch_updated_at
  before update on public.games
  for each row execute function public.touch_updated_at();

drop trigger if exists comments_touch_updated_at on public.comments;
create trigger comments_touch_updated_at
  before update on public.comments
  for each row execute function public.touch_updated_at();

-- Every new auth user gets a profile and an explicit role row. Running as
-- `security definer` is required because the inserting role is the auth service,
-- which has no rights on `public`.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  generated_username text;
begin
  generated_username := 'user_' || substr(replace(new.id::text, '-', ''), 1, 12);

  insert into public.profiles (id, username, display_name)
  values (
    new.id,
    generated_username,
    coalesce(nullif(split_part(coalesce(new.email, ''), '@', 1), ''), generated_username)
  )
  on conflict (id) do nothing;

  insert into public.user_roles (user_id, role)
  values (new.id, 'user')
  on conflict (user_id) do nothing;

  return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- Usernames must be unique, but that should surface as a readable error rather
-- than a raw constraint violation.
comment on constraint profiles_username_format on public.profiles is
  'Usernames are lowercase, 3-24 characters, letters/digits/underscore; unique case-insensitively.';
